# 20 · Felucca's other sound engines
ENG = [("ANALOG", "anlg", "Virtual analog: two oscillators (WAVE: SAW, SQR, TRI, SIN, PWM, SYNC, SUB), noise, drive and a resonant filter, low-pass, band-pass or high-pass (EDIT › FILTER).", "Analogique virtuel : deux oscillateurs (WAVE : SAW, SQR, TRI, SIN, PWM, SYNC, SUB), bruit, saturation et un filtre résonant, passe-bas, passe-bande ou passe-haut (EDIT › FILTER).", "CUT RES ATK REL", "12"),
       ("FM6", "fm6", "Six-operator FM: 32 algorithms, a full patch per track, edited on EDIT › OPERATOR, OP ENV and OPERATOR 2, one operator at a time; SLOT selects a factory patch (F1–F8), the track's own (OWN) or a voice of the bank sent by the web editor (B1–B32).", "FM à six opérateurs : 32 algorithmes, un patch complet par piste, réglé dans EDIT › OPERATOR, OP ENV et OPERATOR 2, un opérateur à la fois ; SLOT choisit un patch d'usine (F1–F8), celui de la piste (OWN) ou une voix de la banque envoyée par l'éditeur web (B1–B32).", "MLVL MRAT MEG SLOT", "8"),
       ("PHASE", "phas", "Phase distortion, with a second waveform, a second detuned voice mixed in or ring-modulated, a sub-oscillator and a wavefolder (FOLD).", "Distorsion de phase, avec une deuxième forme d'onde, une seconde voix désaccordée, mélangée ou modulée en anneau, un sous-oscillateur et un replieur d'onde (FOLD).", "DCW ENV DTN REL", "6"),
       ("LOFI", "lofi", "Chiptune: pulse, triangle, saw, noise and a wave RAM, stepped envelope, pitch sweep and arpeggio.", "Chiptune : impulsion, triangle, dent de scie, bruit et une RAM d'onde, enveloppe en paliers, balayage de hauteur et arpège.", "WAVE DUTY CRSH REL", "5"),
       ("SAMPLE", "smpl", "Multisampled instruments (PIANO, FLUTE and SAX) and three user slots USR1 to USR3 that you fill from the web editor.", "Instruments multi-échantillonnés, PIANO, FLUTE et SAX, et trois emplacements utilisateur USR1 à USR3 que vous remplissez depuis l'éditeur web.", "SET CUT ATK REL", "3"),
       ("VOICE", "vocl", "A singing formant voice: the vowels A E I O U with glides between them (TALK), breath and buzz.", "Une voix chantée à formants : les voyelles A E I O U, glissées (TALK), souffle et bourdonnement.", "VOWL BUZZ BRTH TALK", "4"),
       ("TRIO", "trio", "Three oscillators with ring modulation and sync, into a 12 dB multimode filter, in the style of 8-bit computers.", "Trois oscillateurs avec modulation en anneau et synchro, dans un filtre multimode 12 dB, à la manière des ordinateurs 8 bits.", "CUT RES PW INT2", "5"),
       ("WHEEL", "whel", "A tonewheel organ: 16 drawbar registrations, percussion, key click, drive and a rotary speaker.", "Un orgue à roues phoniques : 16 registrations de tirettes, percussion, clic de touche, saturation et cabine rotative.", "REG PERC DRV ROTR", "5"),
       ("GRAIN", "gran", "Granular textures made from the samples (built-in or user): position, size, density, spread.", "Textures granulaires faites à partir des échantillons (intégrés ou utilisateur) : position, taille, densité, dispersion.", "POS SIZE DENS SPRD", "4"),
       ("PHYS", "phys", "Physical models: modal resonators, strings, struck membranes and sympathetic strings.", "Modèles physiques : résonateurs modaux, cordes, membranes frappées et cordes sympathiques.", "STRC BRIT DAMP POS", "9"),
       ("NOISE", "nois", "Noises from analog to digital: colors, crackle, shift-register and metallic tones.", "Des bruits de l'analogique au numérique : couleurs, crépitements, registres à décalage et sons métalliques.", "FREQ RES COLR REL", "4"),
       ("SLICE", "slce", "A drum break, a piano note or your own sample, cut into slices, one per key; the slices can be set by hand on EDIT › SLICES.", "Un break de batterie, une note de piano ou votre propre échantillon, découpés en tranches, une par touche ; les tranches se règlent à la main dans EDIT › SLICES.", "SRC DIV PTCH DCAY", "2"),
       ("DRUM", "drum", "An 8-lane drum kit (KICK, SNARE, CLAP, HAT CL, HAT OP, TOM, RIM, BELL) on the General MIDI key map, all synthesized: STD and the kits 80, 10, 66, 55, 77, DEEP, TIGHT and PERC; lane levels on EDIT › LANES.", "Une batterie à huit voies (KICK, SNARE, CLAP, HAT CL, HAT OP, TOM, RIM, BELL) sur la répartition General MIDI, toute synthétisée : STD et les kits 80, 10, 66, 55, 77, DEEP, TIGHT et PERC ; niveaux des voies dans EDIT › LANES.", "TUNE TONE DECY SNAP", "4")]
CH("engines", "Felucca's other sound engines", "Les autres moteurs sonores de Felucca",
 P2("Besides P600, each track can use one of thirteen Felucca engines. Change a track's engine by turning PRESETS past the P600 sounds, on SAVE › PRESETS with KNOB 2 (ENG), or by holding EDIT and pressing the engine's key (chapter {ch:layers}). Each engine has its own pages on EDIT (EDIT 1, EDIT 2, then VOICE, VOICE 2, VOICE 3), and its four main settings on HOME.",
    "En plus du moteur P600, chaque piste peut utiliser l'un des treize moteurs de Felucca. Changez le moteur d'une piste en tournant PRESETS au-delà des sons P600, sur SAVE › PRESETS avec KNOB 2 (ENG), ou en maintenant EDIT et en appuyant sur la touche du moteur (chapitre {ch:layers}). Chaque moteur a ses propres pages dans EDIT (EDIT 1, EDIT 2, puis VOICE, VOICE 2, VOICE 3), et ses quatre réglages principaux sur HOME.") +
 table([("Engine", "Moteur"), ("What it is", "Ce que c'est"), ("HOME knobs", "Boutons rotatifs (HOME)"), ("Sounds", "Sons")],
       [[f"<b>{n}</b>", (a, b), k, c] for n, _i, a, b, k, c in ENG]) +
 '<div class="shotrow">' + shot("shots/eng_anlg.png", "ANALOG: EDIT 1.", "ANALOG : EDIT 1.", 180) +
 shot("shots/eng_fm6.png", "FM6: EDIT › OPERATOR.", "FM6 : EDIT › OPERATOR.", 180) +
 shot("shots/eng_slce.png", "SLICE: EDIT › SLICES.", "SLICE : EDIT › SLICES.", 180) +
 shot("shots/eng_drum.png", "DRUM: the drum grid (SEQ › STEP).", "DRUM : la grille de batterie (SEQ › STEP).", 180) + '</div>' +
 H3("Samples: NO SAMPLE", "Échantillons : NO SAMPLE") +
 LI([("SAMPLE, GRAIN and SLICE can play your own samples from the user slots USR1, USR2 and USR3. Send them from the Felucca web editor (the editor link on the installation page). The FM-1 cannot record a sample.",
      "SAMPLE, GRAIN et SLICE peuvent jouer vos propres échantillons depuis les emplacements USR1, USR2 et USR3. Envoyez-les depuis l'éditeur web de Felucca (le lien vers l'éditeur sur la page d'installation). Le FM-1 ne sait pas enregistrer un échantillon."),
     ("An empty slot plays a plain sine wave at the note's pitch, and the band says NO SAMPLE, once per track and slot.",
      "Un emplacement vide joue une simple sinusoïde à la hauteur de la note, et le bandeau indique NO SAMPLE, une fois par piste et par emplacement."),
     ("On the Guru-600, the third slot (USR3) holds 68 KB instead of 80 KB.",
      "Sur le Guru-600, le troisième emplacement (USR3) contient 68 Ko au lieu de 80.")]) +
 H3("Good to know", "Bon à savoir") +
 LI([("A DRUM track plays its kit on the keys and shows a grid instead of the piano roll on SEQ › STEP (chapter {ch:seq}). Its sounds ignore the envelope, glide and chord keys.",
      "Une piste DRUM joue son kit sur les touches et affiche une grille au lieu du piano roll sur SEQ › STEP (chapitre {ch:seq}). Ses sons ignorent l'enveloppe, le glide et les accords."),
     ("SLICE plays one slice per key, from the lowest key upward, ignoring the scale.", "SLICE joue une tranche par touche, de la touche la plus grave vers le haut, sans tenir compte de la gamme."),
     ("VOICE plays four notes at most, GRAIN and PHYS three, P600 and FM6 six, the others eight (within the FM-1's eight voices).",
      "VOICE joue quatre notes au plus, GRAIN et PHYS trois, P600 et FM6 six, les autres huit (dans la limite des huit voix du FM-1)."),
     ("The FM6 patches and samples are edited in the Felucca web editor, which also makes full backups.", "Les patchs FM6 et les échantillons se règlent dans l'éditeur web de Felucca, qui fait aussi des sauvegardes complètes.")]) +
 felucca("Engines", "Felucca's engines page describes each engine and its settings.",
         "La page des moteurs de Felucca décrit chaque moteur et ses réglages."))
